@pytest.fixture
def plist_file(tmp_path):
    """Factory that materializes plist content inside a temporary directory."""
    def _write(content, name='sample.plist'):
        path = tmp_path / name
        if isinstance(content, bytes):
            path.write_bytes(content)
        else:
            path.write_text(content, encoding='utf-8')
        return str(path)
    return _write


@pytest.fixture
def parse_plist(plist_file):
    """Factory that parses in-memory plist content through the public PBPlist API."""
