    return _parse

"""End-to-end tests for the public PBPlist interface."""

import codecs
from pathlib import Path

import pytest

from jc.parsers.pbPlist.pbItem import (
    pbArray,
    pbData,
    pbDictionary,
    pbItemResolver,
    pbString,
)
from jc.parsers.pbPlist.pbPlist import PBPlist


PBXPROJ = """// !$*UTF8*$!
{
\tarchiveVersion = 1;
\tclasses = {
\t};
\tobjectVersion = 46;
\tobjects = {
\t\tAAAA = {
\t\t\tisa = PBXFileReference;
\t\t\tname = "hello world.txt";
\t\t\tpath = hello.txt;
\t\t\tsourceTree = "<group>";
\t\t};
\t};
\trootObject = AAAA;
}
"""


def test_parse_pbxproj_dictionary(parse_plist):
    plist = parse_plist(PBXPROJ, 'project.pbxproj')

    assert plist.file_type == 'ascii'
    assert plist.string_encoding == 'UTF8'
    assert isinstance(plist.root, pbDictionary)
    assert plist.root.nativeType() == {
        'archiveVersion': '1',
        'classes': {},
        'objectVersion': '46',
        'objects': {
            'AAAA': {
                'isa': 'PBXFileReference',
                'name': 'hello world.txt',
                'path': 'hello.txt',
                'sourceTree': '<group>',
            },
        },
        'rootObject': 'AAAA',
    }


def test_parse_root_array(parse_plist):
    plist = parse_plist('(\n\tone,\n\ttwo,\n\t"three"\n)\n')

    assert plist.file_type == 'ascii'
    assert isinstance(plist.root, pbArray)
    assert plist.root.nativeType() == ['one', 'two', 'three']


def test_parse_root_scalar_string(parse_plist):
    plist = parse_plist('simpleValue\n')

    assert isinstance(plist.root, pbString)
    assert plist.root.nativeType() == 'simpleValue'
    assert str(plist.root) == 'simpleValue'


def test_parse_nested_dicts_arrays_and_data(parse_plist):
    content = (
        '{\n'
        '\tlist = (1, 2, (3, 4));\n'
        '\tnested = { inner = "value"; };\n'
        '\tblob = <1020>;\n'
        '}\n'
    )
    plist = parse_plist(content)

    native = plist.root.nativeType()

    assert native['list'] == ['1', '2', ['3', '4']]
    assert native['nested'] == {'inner': 'value'}
    assert native['blob'] == bytearray(b'\x10\x20')


def test_comments_are_ignored_while_parsing(parse_plist):
    content = (
        '// leading line comment\n'
        '/* leading block comment */\n'
        '{\n'
        '\ta = b; // trailing line comment\n'
        '\t/* between entries */\n'
        '\tc = d;\n'
        '}\n'
    )
    plist = parse_plist(content)

    assert plist.root.nativeType() == {'a': 'b', 'c': 'd'}


def test_annotation_from_trailing_comment_is_kept_on_value(parse_plist):
    plist = parse_plist('{ a = b /* note */; c = "d" /* quoted */; }\n')

    assert plist.root['a'].annotation == ' note '
    assert plist.root['c'].annotation == ' quoted '
    # annotations are not part of the native value
    assert plist.root.nativeType() == {'a': 'b', 'c': 'd'}


def test_escaped_characters_in_quoted_string(parse_plist):
    plist = parse_plist('{ s = "a\\nb\\tc\\"d\\U00e9"; }\n')

    assert plist.root.nativeType() == {'s': 'a\nb\tc"d\u00e9'}


def test_strings_file_extension_wraps_contents(parse_plist):
    plist = parse_plist(
        '"greeting" = "hello";\n"farewell" = "bye";\n',
        'Localizable.strings',
    )

    assert plist.file_type == 'ascii'
    assert plist.string_encoding is None
    assert plist.root.nativeType() == {'greeting': 'hello', 'farewell': 'bye'}


def test_strings_file_key_without_value_uses_key_as_value(parse_plist):
    plist = parse_plist('"key";\n', 'Localizable.strings')

    assert plist.root.nativeType() == {'key': 'key'}


def test_encoding_hint_is_extracted(parse_plist):
    plist = parse_plist('// !$*UTF16*$!\n{ a = b; }\n')

    assert plist.string_encoding == 'UTF16'
    assert plist.root.nativeType() == {'a': 'b'}


def test_no_encoding_hint_leaves_encoding_unset(parse_plist):
    plist = parse_plist('// a normal comment\n{ a = b; }\n')

    assert plist.string_encoding is None


def test_missing_file_yields_empty_plist(tmp_path):
    missing = tmp_path / 'does-not-exist.plist'

    plist = PBPlist(str(missing))

    assert plist.root is None
    assert not hasattr(plist, 'file_path')


@pytest.mark.parametrize('content', [
    'bplist00binarygarbage',
    '<?xml version="1.0" encoding="UTF-8"?><plist><dict/></plist>',
])
def test_unsupported_container_formats_are_not_parsed(parse_plist, content, tmp_path):
    plist = parse_plist(content)

    assert plist.root is None
    assert plist.file_type is None

    # writing an empty root does not create a file
    target = tmp_path / 'out.plist'
    plist.write(str(target))
    assert not target.exists()


def test_write_to_explicit_path(parse_plist, tmp_path):
    plist = parse_plist(PBXPROJ, 'project.pbxproj')
    target = tmp_path / 'written.pbxproj'

    plist.write(str(target))

    text = target.read_text(encoding='utf-8')
    assert text.startswith('// !$*UTF8*$!\n')
    assert 'archiveVersion = 1;' in text
    assert 'isa = PBXFileReference;' in text
    assert 'name = "hello world.txt";' in text
    assert text.count('/* Begin PBXFileReference section */') == 1
    assert text.count('/* End PBXFileReference section */') == 1


def test_write_defaults_to_source_path(parse_plist, plist_file):
    path = plist_file('{ a = b; }\n', 'inplace.plist')
    plist = PBPlist(path)

    plist.write()

    text = Path(path).read_text(encoding='utf-8')
    assert text == '{\n\ta = b;\n}'


def test_write_omits_encoding_header_when_no_hint(parse_plist, tmp_path):
    plist = parse_plist('{ a = b; }\n')
    target = tmp_path / 'out.plist'

    plist.write(str(target))

    text = target.read_text(encoding='utf-8')
    assert '// !$*' not in text
    assert text == '{\n\ta = b;\n}'


def test_write_parse_roundtrip_preserves_native_values(parse_plist, tmp_path):
    plist = parse_plist(PBXPROJ, 'project.pbxproj')
    expected = plist.root.nativeType()
    target = tmp_path / 'roundtrip.pbxproj'

    plist.write(str(target))
    reloaded = PBPlist(str(target))

    assert reloaded.file_type == 'ascii'
    assert reloaded.string_encoding == 'UTF8'
    assert reloaded.root.nativeType() == expected


def test_write_roundtrip_of_data_value(parse_plist, tmp_path):
    plist = parse_plist('{ blob = <1020>; }\n')
    target = tmp_path / 'data.plist'

    plist.write(str(target))

    text = target.read_text(encoding='utf-8')
    assert 'blob = <1020>;' in text
    assert PBPlist(str(target)).root.nativeType() == {'blob': bytearray(b'\x10\x20')}


def test_annotation_roundtrip(parse_plist, tmp_path):
    plist = parse_plist('{ a = b /* note */; }\n')
    target = tmp_path / 'annotated.plist'

    plist.write(str(target))

    assert '/* note */' in target.read_text(encoding='utf-8')


def test_root_is_assignable_and_serializable(parse_plist, tmp_path):
    plist = parse_plist('{ a = b; }\n')
    new_root = pbItemResolver('standalone', 'string')
    plist.root = new_root
    target = tmp_path / 'replaced.plist'

    plist.write(str(target))

    assert target.read_text(encoding='utf-8') == 'standalone'


def test_parse_preserves_key_order_from_file(parse_plist):
    plist = parse_plist('{ zebra = 1; apple = 2; mango = 3; }\n')

    assert [str(key) for key in plist.root] == ['zebra', 'apple', 'mango']
    assert list(plist.root.nativeType()) == ['zebra', 'apple', 'mango']


def test_parse_uses_string_items_for_unquoted_and_quoted_keys(parse_plist):
    plist = parse_plist('{ plain = 1; "quoted key" = 2; }\n')

    keys = list(plist.root)

    assert [(str(key), key.type_name) for key in keys] == [
        ('plain', 'string'),
        ('quoted key', 'qstring'),
    ]
    # both key flavors are usable as plain string lookups
    assert plist.root['plain'].nativeType() == '1'
    assert plist.root['quoted key'].nativeType() == '2'


def test_duplicate_dictionary_keys_keep_one_entry_with_last_value(parse_plist):
    plist = parse_plist('{ a = 1; a = 2; }\n')

    assert len(plist.root) == 1
    assert [str(key) for key in plist.root] == ['a']
    assert plist.root.nativeType() == {'a': '2'}


def test_parse_root_data(parse_plist):
    plist = parse_plist('<1020>\n')

    assert isinstance(plist.root, pbData)
    assert plist.root.nativeType() == bytearray(b'\x10\x20')


def test_parse_array_mixes_item_types(parse_plist):
    plist = parse_plist('(one, { a = b; }, <1020>)\n')

    assert [type(item).__name__ for item in plist.root] == [
        'pbString',
        'pbDictionary',
        'pbData',
    ]
    assert plist.root.nativeType() == ['one', {'a': 'b'}, bytearray(b'\x10\x20')]


def test_nested_dictionaries_are_pbroot_backed(parse_plist):
    plist = parse_plist('{ objects = { A = { isa = X; }; }; }\n')
    objects = plist.root['objects']

    assert isinstance(objects, pbDictionary)
    assert inner_root_type(objects) == 'pbRoot'
    assert objects.nativeType() == {'A': {'isa': 'X'}}
    assert plist.root['objects']['A']['isa'].nativeType() == 'X'


def inner_root_type(dictionary_item):
    from jc.parsers.pbPlist.pbRoot import pbRoot as root_class
    assert isinstance(dictionary_item.value, root_class)
    return type(dictionary_item.value).__name__


def test_parsed_plist_exposes_source_metadata(plist_file):
    path = plist_file('{ a = b; }\n', 'meta.plist')

    plist = PBPlist(path)

    assert plist.file_path == path
    assert plist.file_type == 'ascii'
    assert plist.root.nativeType() == {'a': 'b'}


def test_parse_utf8_bom_file(plist_file):
    path = plist_file(codecs.BOM_UTF8 + b'{ greeting = "hi"; }', 'bom.plist')

    plist = PBPlist(path)

    assert plist.root.nativeType() == {'greeting': 'hi'}


def test_parse_utf16_file(plist_file):
    path = plist_file(
        codecs.BOM_UTF16 + '{ greeting = "hi"; }'.encode('utf-16-le'),
        'utf16.plist',
    )

    plist = PBPlist(path)

    assert plist.file_type == 'ascii'
    assert plist.root.nativeType() == {'greeting': 'hi'}

"""Tests for the StrParse helper functions."""

import pytest

from jc.parsers.pbPlist import StrParse


@pytest.mark.parametrize('character', ['0', '7', '5'])
def test_is_octal_number_true(character):
    assert StrParse.IsOctalNumber(character) is True


@pytest.mark.parametrize('character', ['8', '9', 'a', ' '])
def test_is_octal_number_false(character):
    assert StrParse.IsOctalNumber(character) is False


@pytest.mark.parametrize('character', ['0', 'a', 'f', 'F', '9'])
def test_is_hex_number_true(character):
    assert StrParse.IsHexNumber(character) is True


@pytest.mark.parametrize('character', ['g', 'z', ' '])
def test_is_hex_number_false(character):
    assert StrParse.IsHexNumber(character) is False


@pytest.mark.parametrize('character,expected', [
    ('\a', '\\a'),
    ('\b', '\\b'),
    ('\f', '\\f'),
    ('\n', '\\n'),
    ('\r', '\\r'),
    ('\t', '\\t'),
    ('\v', '\\v'),
    ('"', '\\"'),
    ('x', 'x'),
    (' ', ' '),
])
def test_sanitize_character(character, expected):
    assert StrParse.SanitizeCharacter(character) == expected


@pytest.mark.parametrize('raw,expected', [
    (r'a\nb\tc', 'a\nb\tc'),
    (r'\r\f\v', '\r\f\v'),
    (r'\a\b', '\a\b'),
    (r'escaped \" quote', 'escaped " quote'),
    (r'caf\U00e9', 'caf\u00e9'),
    ('plain text', 'plain text'),
    ('line\\\nbreak', 'line\nbreak'),
])
def test_unquotify_string_escapes(raw, expected):
    assert StrParse.UnQuotifyString(raw, 0, len(raw)) == expected


def test_unquotify_string_only_processes_requested_range():
    assert StrParse.UnQuotifyString('xxhelloyy', 2, 7) == 'hello'


def test_unquotify_string_keeps_unknown_escape_sequence():
    assert StrParse.UnQuotifyString(r'a\qb', 0, 4) == r'a\qb'


@pytest.mark.parametrize('string_data,index,expected', [
    ('a\nb\nc', 0, 1),
    ('a\nb\nc', 2, 2),
    ('a\nb\nc', 4, 3),
    ('abc', 2, 1),
    ('a\rb', 2, 2),
    ('a\nb', 100, 2),
])
def test_line_number_for_index(string_data, index, expected):
    assert StrParse.LineNumberForIndex(string_data, index) == expected


@pytest.mark.parametrize('character', list('abcXYZ019_$/:.-'))
def test_valid_unquoted_string_characters(character):
    assert StrParse.IsValidUnquotedStringCharacter(character) is True


@pytest.mark.parametrize('character', ['@', ' ', '"', '{', '\n', '#'])
def test_invalid_unquoted_string_characters(character):
    assert StrParse.IsValidUnquotedStringCharacter(character) is False


def test_unquoted_string_character_requires_single_character():
    with pytest.raises(ValueError, match='single characters'):
        StrParse.IsValidUnquotedStringCharacter('ab')


@pytest.mark.parametrize('character,special,regular,formatting,newline,end_of_line', [
    ('\t', True, False, True, False, False),
    ('\n', True, False, True, True, True),
    ('\r', True, False, True, True, True),
    ('\x0b', True, False, False, False, False),
    ('\x0c', True, False, False, False, False),
    (' ', False, True, True, False, False),
    ('\u2028', False, True, True, False, True),
    ('\u2029', False, True, True, False, True),
    ('a', False, False, False, False, False),
])
def test_whitespace_predicates(character, special, regular, formatting, newline, end_of_line):
    assert StrParse.IsSpecialWhitespace(character) is special
    assert StrParse.IsRegularWhitespace(character) is regular
    assert StrParse.IsDataFormattingWhitespace(character) is formatting
    assert StrParse.IsNewline(character) is newline
    assert StrParse.IsEndOfLine(character) is end_of_line


@pytest.mark.parametrize('hex_digits,expected', [
    ('80', 'a0'),
    ('9d', 'b5'),
    ('a4', '44'),
    ('ff', 'fd'),
])
def test_convert_nextstep_to_unicode(hex_digits, expected):
    assert StrParse.ConvertNEXTSTEPToUnicode(hex_digits) == expected


def test_convert_nextstep_unknown_codepoint_raises():
    with pytest.raises(KeyError):
        StrParse.ConvertNEXTSTEPToUnicode('20')


def test_unichr():
    assert StrParse.unichr(65) == 'A'


def test_index_of_next_non_space_stops_on_content():
    assert StrParse.IndexOfNextNonSpace('abc', 0) == (True, 0, '')
    assert StrParse.IndexOfNextNonSpace('   abc', 0) == (True, 3, '')


def test_index_of_next_non_space_consumes_block_comment():
    assert StrParse.IndexOfNextNonSpace('  /* note */  abc', 0) == (True, 14, ' note ')


def test_index_of_next_non_space_consumes_line_comment():
    assert StrParse.IndexOfNextNonSpace('// hello\nabc', 0) == (True, 9, ' hello')


def test_index_of_next_non_space_at_end_of_line_comment():
    # the comment runs to the end of the data, so no content is found afterwards
    assert StrParse.IndexOfNextNonSpace('// hello\n', 0) == (False, 9, ' hello')


def test_index_of_next_non_space_at_plain_content():
    assert StrParse.IndexOfNextNonSpace('// hello\nabc', 9) == (True, 9, '')


def test_index_of_next_non_space_trailing_slash_is_not_a_comment():
    assert StrParse.IndexOfNextNonSpace('abc/', 3) == (True, 3, '')


@pytest.mark.parametrize('string_data,current_index,expected', [
    ('', 0, (False, 0, '')),
    ('   ', 0, (False, 3, '')),
    ('abc', 5, (False, 5, '')),
    ('/* unterminated', 0, (False, 15, ' unterminated')),
])
def test_index_of_next_non_space_without_content(string_data, current_index, expected):
    assert StrParse.IndexOfNextNonSpace(string_data, current_index) == expected
